    @Transactional(readOnly = true)
    public TrainView getTrain(String trainKey) {
        throw new UnsupportedOperationException();
    }

    /** 查询文档下全部列车，按 trainKey 稳定升序。 */
    @Transactional(readOnly = true)
    public List<TrainView> listTrains(long documentId) {
        throw new UnsupportedOperationException();
    }

